//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    /// Returns `true` for transient faults that may be retried and `false`
    /// for permanent faults that must abort immediately.
    pub fn is_transient(&self) -> bool {
        matches!(self, RetryError::Transient(_))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn transient_errors_are_retryable() {
        assert!(RetryError::Transient("blip".into()).is_transient());
    }

    #[test]
    fn permanent_errors_are_not_retryable() {
        assert!(!RetryError::Permanent("bad input".into()).is_transient());
    }
}

//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Upper bound for any single retry delay, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Delay in milliseconds to wait before the `retry`-th retry (0-based).
    ///
    /// The delay grows exponentially from `base_delay_ms`:
    /// `min(base_delay_ms * 2^retry, max_delay_ms)`. The exponent is capped
    /// and all arithmetic is saturating, so very large retry counts never
    /// overflow and simply saturate at [`RetryConfig::max_delay_ms`].
    pub fn retry_delay_ms(&self, retry: u32) -> u64 {
        // Cap the exponent so `1u64 << exponent` can never overflow.
        let exponent = retry.min(63);
        let doubled = self.base_delay_ms.saturating_mul(1u64 << exponent);
        doubled.min(self.max_delay_ms)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn config(base_delay_ms: u64, max_delay_ms: u64) -> RetryConfig {
        RetryConfig {
            max_attempts: 5,
            base_delay_ms,
            max_delay_ms,
        }
    }

    #[test]
    fn first_retry_uses_base_delay() {
        assert_eq!(config(100, 10_000).retry_delay_ms(0), 100);
    }

    #[test]
    fn delay_grows_exponentially() {
        let cfg = config(10, 10_000);
        assert_eq!(cfg.retry_delay_ms(0), 10);
        assert_eq!(cfg.retry_delay_ms(1), 20);
        assert_eq!(cfg.retry_delay_ms(2), 40);
        assert_eq!(cfg.retry_delay_ms(3), 80);
        assert_eq!(cfg.retry_delay_ms(4), 160);
    }

    #[test]
    fn delay_saturates_at_max_delay() {
        let cfg = config(10, 100);
        assert_eq!(cfg.retry_delay_ms(0), 10);
        assert_eq!(cfg.retry_delay_ms(3), 80);
        assert_eq!(cfg.retry_delay_ms(4), 100);
        assert_eq!(cfg.retry_delay_ms(5), 100);
        assert_eq!(cfg.retry_delay_ms(1000), 100);
    }

    #[test]
    fn max_delay_below_base_saturates_immediately() {
        let cfg = config(1000, 10);
        assert_eq!(cfg.retry_delay_ms(0), 10);
        assert_eq!(cfg.retry_delay_ms(10), 10);
    }

    #[test]
    fn huge_retry_counts_do_not_overflow() {
        let cfg = config(u64::MAX, 1234);
        for retry in [0u32, 1, 2, 63, 64, 1000, u32::MAX] {
            assert_eq!(cfg.retry_delay_ms(retry), 1234);
        }
    }
}

//! Injected sleeper so tests never really wait.
pub trait Sleeper {
    fn sleep_ms(&mut self, ms: u64);
}

/// Records every requested delay instead of waiting.
#[derive(Debug, Default)]
pub struct FakeSleeper {
    pub sleeps: Vec<u64>,
}

impl Sleeper for FakeSleeper {
    fn sleep_ms(&mut self, ms: u64) {
        self.sleeps.push(ms);
    }
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
///
/// Retry policy:
/// - `max_attempts` is the total number of attempts, including the first
///   call.
/// - Only [`RetryError::Transient`] failures are retried; permanent
///   failures return immediately.
/// - Delays between retries grow exponentially from `base_delay_ms`
///   (`base_delay_ms * 2^retry`) and saturate at `max_delay_ms`.
/// - Once the budget is exhausted, the last error is returned.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    let mut attempt: u32 = 1;
    loop {
        match job() {
            Ok(()) => return Ok(()),
            Err(err) if !err.is_transient() => return Err(err),
            Err(err) => {
                if attempt >= config.max_attempts {
                    return Err(err);
                }
                sleeper.sleep_ms(config.retry_delay_ms(attempt - 1));
                attempt += 1;
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn config(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> RetryConfig {
        RetryConfig {
            max_attempts,
            base_delay_ms,
            max_delay_ms,
        }
    }

    fn transient(msg: &str) -> RetryError {
        RetryError::Transient(msg.to_string())
    }

    #[test]
    fn success_on_first_attempt_returns_ok_without_sleeping() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(3, 10, 100), &mut sleeper, || {
            calls += 1;
            Ok(())
        });
        assert_eq!(result, Ok(()));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn permanent_error_returns_immediately() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(5, 10, 100), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Permanent("nope".into()))
        });
        assert_eq!(result, Err(RetryError::Permanent("nope".into())));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn max_attempts_includes_first_call() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(3, 10, 1000), &mut sleeper, || {
            calls += 1;
            Err(transient("flaky"))
        });
        assert_eq!(result, Err(transient("flaky")));
        assert_eq!(calls, 3);
        assert_eq!(sleeper.sleeps, vec![10, 20]);
    }

    #[test]
    fn succeeds_after_retries() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(5, 10, 1000), &mut sleeper, || {
            calls += 1;
            if calls < 3 {
                Err(transient("flaky"))
            } else {
                Ok(())
            }
        });
        assert_eq!(result, Ok(()));
        assert_eq!(calls, 3);
        assert_eq!(sleeper.sleeps, vec![10, 20]);
    }

    #[test]
    fn delays_saturate_at_max_delay() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(6, 10, 30), &mut sleeper, || {
            calls += 1;
            Err(transient("flaky"))
        });
        assert_eq!(result, Err(transient("flaky")));
        assert_eq!(calls, 6);
        assert_eq!(sleeper.sleeps, vec![10, 20, 30, 30, 30]);
    }

    #[test]
    fn single_attempt_when_max_attempts_is_one() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(1, 10, 100), &mut sleeper, || {
            calls += 1;
            Err(transient("flaky"))
        });
        assert_eq!(result, Err(transient("flaky")));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }
}

# jobrunner

Small job runner with a pluggable retry policy.

## Retry policy

`run_job` executes the job with a bounded exponential retry policy:

- `max_attempts` is the total number of attempts, including the first call.
- Only transient errors (`RetryError::Transient`) are retried; permanent
  errors (`RetryError::Permanent`) return immediately.
- Delays between retries grow exponentially from `base_delay_ms`
  (`base_delay_ms * 2^retry`) and saturate at `max_delay_ms`. The
  arithmetic is saturating, so large retry counts never overflow.
- When the budget is exhausted, the last error is returned.

## Configuration

`RetryConfig` exposes three public fields:

- `max_attempts: u32` — total attempts, including the first call (>= 1).
- `base_delay_ms: u64` — delay before the first retry, in milliseconds.
- `max_delay_ms: u64` — upper bound for any retry delay, in milliseconds.

## Example

```rust
use jobrunner::{FakeSleeper, RetryConfig, RetryError, run_job};

let config = RetryConfig {
    max_attempts: 4,
    base_delay_ms: 10,
    max_delay_ms: 100,
};
let mut sleeper = FakeSleeper::default();

// Every attempt is transient, so the run ends when the budget runs out.
let result = run_job(&config, &mut sleeper, || {
    Err(RetryError::Transient("temporary blip".into()))
});

assert!(result.is_err());
assert_eq!(sleeper.sleeps, vec![10, 20, 40]);
```

//! End-to-end coverage of the public retry policy API.

use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError, Sleeper};

fn config(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> RetryConfig {
    RetryConfig {
        max_attempts,
        base_delay_ms,
        max_delay_ms,
    }
}

fn transient(msg: &str) -> RetryError {
    RetryError::Transient(msg.to_string())
}

#[test]
fn retries_transient_failures_until_success() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(&config(5, 25, 1000), &mut sleeper, || {
        calls += 1;
        if calls < 4 {
            Err(transient("flaky"))
        } else {
            Ok(())
        }
    });
    assert_eq!(result, Ok(()));
    assert_eq!(calls, 4);
    assert_eq!(sleeper.sleeps, vec![25, 50, 100]);
}

#[test]
fn permanent_error_returns_immediately() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(&config(10, 25, 1000), &mut sleeper, || {
        calls += 1;
        Err(RetryError::Permanent("bad request".into()))
    });
    assert_eq!(result, Err(RetryError::Permanent("bad request".into())));
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}

#[test]
fn backoff_saturates_at_max_delay_and_never_overflows() {
    // A huge base delay with many retries: every recorded delay must be
    // exactly `max_delay_ms`, and the run must complete without panicking.
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(&config(10, u64::MAX, 500), &mut sleeper, || {
        calls += 1;
        Err(transient("flaky"))
    });
    assert_eq!(result, Err(transient("flaky")));
    assert_eq!(calls, 10);
    assert_eq!(sleeper.sleeps, vec![500; 9]);
}

#[test]
fn max_attempts_includes_the_first_call() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(&config(2, 25, 1000), &mut sleeper, || {
        calls += 1;
        Err(transient("flaky"))
    });
    assert_eq!(result, Err(transient("flaky")));
    assert_eq!(calls, 2);
    assert_eq!(sleeper.sleeps, vec![25]);
}

#[test]
fn works_with_custom_sleeper() {
    struct RecordingSleeper {
        total: u64,
    }
    impl Sleeper for RecordingSleeper {
        fn sleep_ms(&mut self, ms: u64) {
            self.total += ms;
        }
    }

    let mut sleeper = RecordingSleeper { total: 0 };
    let mut calls = 0;
    let result = run_job(&config(4, 10, 1000), &mut sleeper, || {
        calls += 1;
        if calls < 4 {
            Err(transient("flaky"))
        } else {
            Ok(())
        }
    });
    assert_eq!(result, Ok(()));
    assert_eq!(calls, 4);
    assert_eq!(sleeper.total, 10 + 20 + 40);
}
